    is_prime = [True] * (max_n + 1)

    for p in range(2, max_n + 1):
        if is_prime[p]:
            # Mark multiples of p
            for multiple in range(p, max_n + 1, p):
                if multiple != p:
                    is_prime[multiple] = False
                mu[multiple] *= -1
            # Mark multiples of p^2
            for multiple in range(p * p, max_n + 1, p * p):
                mu[multiple] = 0

    total = 0
    for d in range(1, K + 1):
        m = K // d
        f_m = 0
        for g in range(1, m + 1):
            f_m += mu[g] * ( (m // g) ** 3 )
        total += d * f_m

    print(total)

